import sys
from collections import defaultdict

def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    rootX = find(x)
    rootY = find(y)
    if rootX != rootY:
        parent[rootX] = rootY

n, m = map(int, sys.stdin.readline().split())
parent = list(range(n + 1))

for _ in range(m):
    a, b = map(int, sys.stdin.readline().split())
